import json, os, re, shutil, sys
B = "D:/rtmp/hr10ds"
S = json.load(open(B + "/shots_timed.json", encoding="utf-8"))
shutil.copyfile(B + "/shots_timed.json", B + "/shots_plan.json")

def have(i):
    for ext in (".jpg", ".jpeg", ".png"):
        if os.path.exists(B + "/fotos/" + i + ext):
            return True
    for d in ("/clips/", "/avatar/frames/"):
        for ext in (".mp4", ".jpg"):
            if os.path.exists(B + d + i + ext):
                return True
    return False

avail = [i for i in dict.fromkeys(x["id"] for x in S) if have(i)]
if not avail:
    sys.exit("no hay fotos")
use = {i: 0 for i in avail}
def fam(i):
    m = re.match(r"([a-z]+)", i)
    return m.group(1) if m else ""
def num(i):
    m = re.search(r"(\d+)", i)
    return int(m.group(1)) if m else 0

out = []
recent = []
rep = 0
for x in S:
    i = x["id"]
    if i in use:
        pick = i
    else:
        cands = [c for c in avail if fam(c) == fam(i) and c not in recent] or [c for c in avail if c not in recent] or avail
        pick = sorted(cands, key=lambda c: (use[c], abs(num(c) - num(i))))[0]
        rep += 1
    use[pick] += 1
    recent = (recent + [pick])[-5:]
    out.append({"id": pick, "startMs": x["startMs"], "endMs": x["endMs"]})
json.dump(out, open(B + "/shots_timed.json", "w", encoding="utf-8"), indent=1)
print("fotos disponibles %d, reemplazos %d, max uso %d" % (len(avail), rep, max(use.values())))

