import json, os, subprocess
B = "D:/rtmp/hr10ds"
R = sorted(json.load(open(B + "/avatar/avatar_ranges.json", encoding="utf-8")), key=lambda r: r["startMs"])
bad = []
for r in R:
    p = B + "/" + r["file"]
    if not os.path.exists(p):
        bad.append((r["file"], "FALTA")); continue
    out = subprocess.run(["ffprobe", "-v", "error", "-show_entries", "format=duration", "-of", "csv=p=0", p],
                         capture_output=True, text=True).stdout.strip()
    try:
        d = float(out)
    except Exception:
        bad.append((r["file"], "ILEGIBLE")); continue
    exp = (r["endMs"] - r["startMs"]) / 1000.0 + 0.3
    if abs(d - exp) > 0.15:
        bad.append((r["file"], "dur %.2f esperado %.2f" % (d, exp)))
print("ventanas %d · problemas %d" % (len(R), len(bad)))
for b in bad: print("  ", b[0], b[1])

